import { mkdtemp, readFile, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { describe, expect, it } from "vitest";
import {
  checkTemplate,
  generatePdf,
  parseLog,
  parseTemplate,
  selectFields,
  supportedLogFormats
} from "./index";

const adif = [
  "Generated by test",
  "<ADIF_VER:5>3.1.4<EOH>",
  "<CALL:5>DL1AA<QSO_DATE:8>20261010<TIME_ON:4>1234<EOR>",
  "<CALL:6>F1BÁR<QSO_DATE:8>20261010<TIME_ON:4>1300<EOR>"
].join("");

const template = `
paper:
  size: A4
  orientation: portrait
labels:
  width: 70
  height: 35
  columns: 3
  rows: 8
  margin: { top: 10, left: 0, right: 0, bottom: 5 }
  safety: { top: 2, left: 2, right: 2, bottom: 2 }
fields:
  - field: CALL
    x: 2
    y: 2
    width: 40
    height: 6
    fontSize: 12
  - text: "73 de [CALL]"
    x: 2
    y: 12
    width: 40
    height: 5
    fontSize: 9
`;

describe("log parsing", () => {
  it("lists ADIF fields and respects UTF-8 byte lengths", () => {
    expect(selectFields(adif)).toEqual(["CALL", "QSO_DATE", "TIME_ON"]);
    expect(parseLog(adif).records[1].CALL).toBe("F1BÁR");
  });

  it("maps Cabrillo QSOs to ADIF-style fields", () => {
    const cabrillo = [
      "START-OF-LOG: 3.0",
      "QSO: 14000 CW 2026-10-10 1234 DL0ME 599 001 DL1AA 599 002"
    ].join("\n");
    const parsed = parseLog(cabrillo);
    expect(parsed.format).toBe("cabrillo");
    expect(parsed.records).toEqual([
      {
        FREQ: "14",
        MODE: "CW",
        QSO_DATE: "20261010",
        TIME_ON: "1234",
        CALL: "DL1AA",
        RST_SENT: "599",
        STX_STRING: "001",
        RST_RCVD: "599",
        SRX_STRING: "002"
      }
    ]);
  });

  it("reads IARU R1 EDI QSO records", () => {
    const edi = [
      "[REG1TEST;1]",
      "TName=Test",
      "[QSORecords;1]",
      "20261010;1234;DL1AA;CW;599;001;599;002;JO31AA;144.174"
    ].join("\n");
    const parsed = parseLog(edi);
    expect(parsed.format).toBe("edi");
    expect(parsed.records[0]).toMatchObject({
      CALL: "DL1AA",
      QSO_DATE: "20261010",
      TIME_ON: "1234",
      GRIDSQUARE: "JO31AA"
    });
  });

  it("allows callers to supply a format when detection is ambiguous", () => {
    expect(parseLog("<CALL:5>DL1AA<EOR>", "adif").records).toHaveLength(1);
  });
});

describe("template checking and PDF generation", () => {
  it("parses and validates the documented YAML template shape", async () => {
    expect(parseTemplate(template).labels.columns).toBe(3);
    await expect(checkTemplate(adif, template)).resolves.toMatchObject({ ok: true, errors: [] });
  });

  it("reports content outside the printable safety area and text overflow", async () => {
    const tooSmall = template
      .replace("width: 40", "width: 2")
      .replace('  - text: "73 de [CALL]"\n    x: 2', '  - text: "73 de [CALL]"\n    x: 1');
    const result = await checkTemplate(adif, tooSmall);
    expect(result.ok).toBe(false);
    expect(result.errors.map(({ code }) => code)).toContain("outside-printable-area");
    expect(result.errors.map(({ code }) => code)).toContain("text-does-not-fit");
  });

  it("reports characters unsupported by a selected standard font", async () => {
    const emojiAdif = "<NAME:4>😀<EOR>";
    const emojiTemplate = `
labels: { width: 70, height: 36, columns: 1, rows: 1 }
fields:
  - { field: NAME, x: 0, y: 0, width: 50, height: 8, fontSize: 12 }
`;
    await expect(checkTemplate(emojiAdif, emojiTemplate)).resolves.toMatchObject({
      ok: false,
      errors: [expect.objectContaining({ code: "unsupported-character" })]
    });
  });

  it("returns PDF bytes and can write them to a file", async () => {
    const bytes = await generatePdf(adif, template);
    expect(bytes).toBeInstanceOf(Uint8Array);
    expect(new TextDecoder().decode(bytes!.subarray(0, 5))).toBe("%PDF-");

    const directory = await mkdtemp(join(tmpdir(), "hamqslprint-"));
    const target = join(directory, "labels.pdf");
    try {
      await expect(generatePdf(adif, template, target)).resolves.toBeUndefined();
      expect((await readFile(target)).subarray(0, 5).toString()).toBe("%PDF-");
    } finally {
      await rm(directory, { recursive: true, force: true });
    }
  });
});

describe("supported log formats", () => {
  it("lists the formats from the project specification", () => {
    expect(supportedLogFormats).toEqual(["adif", "cabrillo", "edi"]);
  });
});
